func newReview() unsafe.Pointer { return unsafe.Pointer(new(formulatemplate.Review)) }

func newNReview(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]formulatemplate.Review, n)))
}

func ptrReview(p unsafe.Pointer, c int32) any {
	r := (*formulatemplate.Review)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.TemplateID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 4:
		return &r.Round
	case 5:
		return (*string)(unsafe.Pointer(&r.Decision))
	case 6:
		return (**string)(unsafe.Pointer(&r.ActorID))
	case 7:
		return &r.Comment
	case 8:
		return &r.BaseVersionNumber
	case 9:
		return (**string)(unsafe.Pointer(&r.RequestedReviewerID))
	case 10:
		return &r.ReviewerNote
	case 11:
		return &r.CreatedAt
	}
	return nil
}

func valueReview(p unsafe.Pointer, c int32) any {
	r := (*formulatemplate.Review)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.TemplateID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.BusinessUnitID)
	case 4:
		return r.Round
	case 5:
		return string(r.Decision)
	case 6:
		if r.ActorID == nil {
			return nil
		}
		return string(*r.ActorID)
	case 7:
		if r.Comment == "" {
			return nil
		}
		return r.Comment
	case 8:
		return r.BaseVersionNumber
	case 9:
		if r.RequestedReviewerID == nil {
			return nil
		}
		return string(*r.RequestedReviewerID)
	case 10:
		if r.ReviewerNote == "" {
			return nil
		}
		return r.ReviewerNote
	case 11:
		return r.CreatedAt
	}
	return nil
}

func attachReview(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*formulatemplate.Review)(p)
	switch rel {
	case 0:
		r.Actor = (*tenant.User)(child)
	case 1:
		r.RequestedReviewer = (*tenant.User)(child)
	}
}

