func ptrVersionImport(p unsafe.Pointer, c int32) any {
	r := (*formulatemplate.VersionImport)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.TemplateVersionID))
	case 1:
		return (*string)(unsafe.Pointer(&r.LibraryID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 4:
		return (*string)(unsafe.Pointer(&r.TemplateID))
	case 5:
		return &r.TemplateVersion
	case 6:
		return &r.LibraryVersionNumber
	case 7:
		return &r.Path
	}
	return nil
}

func valueVersionImport(p unsafe.Pointer, c int32) any {
	r := (*formulatemplate.VersionImport)(p)
	switch c {
	case 0:
		return string(r.TemplateVersionID)
	case 1:
		return string(r.LibraryID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.BusinessUnitID)
	case 4:
		return string(r.TemplateID)
	case 5:
		return r.TemplateVersion
	case 6:
		return r.LibraryVersionNumber
	case 7:
		return r.Path
	}
	return nil
}

