func newVersionTable() unsafe.Pointer { return unsafe.Pointer(new(formulatemplate.VersionTable)) }

func newNVersionTable(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]formulatemplate.VersionTable, n)))
}

func ptrVersionTable(p unsafe.Pointer, c int32) any {
	r := (*formulatemplate.VersionTable)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.TemplateVersionID))
	case 1:
		return (*string)(unsafe.Pointer(&r.RateMatrixID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 4:
		return (*string)(unsafe.Pointer(&r.TemplateID))
	case 5:
		return &r.TemplateVersion
	case 6:
		return &r.MatrixVersionNumber
	case 7:
		return &r.Code
	}
	return nil
}

func valueVersionTable(p unsafe.Pointer, c int32) any {
	r := (*formulatemplate.VersionTable)(p)
	switch c {
	case 0:
		return string(r.TemplateVersionID)
	case 1:
		return string(r.RateMatrixID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.BusinessUnitID)
	case 4:
		return string(r.TemplateID)
	case 5:
		return r.TemplateVersion
	case 6:
		return r.MatrixVersionNumber
	case 7:
		return r.Code
	}
	return nil
}

